internal enum NativeOwnership: String {
    case owned = "OWNED"
    case borrowed = "BORROWED"
    case parentOwned = "PARENT_OWNED"
    case processGlobal = "PROCESS_GLOBAL"
    case managedValue = "MANAGED_VALUE"
}

internal struct NativeManifestEntry {
    /// The exported CNA C symbol.
    let symbol: String
    /// The `NativeFunctions` stored property that holds this route, and nothing else.
    let swiftField: String
    /// The route's own `@convention(c)` type. Every route has one of its own;
    /// no two routes share a type, so a swapped resolution is a named
    /// disagreement rather than a silently compatible alias.
    let routeType: String
    let cReturn: String
    let cParameters: [String]
    let ownership: NativeOwnership
    let resultLifetime: String
    let errorLifetime: String
    let callbackABI: String?
}

